import { readFileSync, writeFileSync } from 'node:fs'
import { resolve, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = dirname(fileURLToPath(import.meta.url))
const root = resolve(__dirname, '..')
const sourcePath = resolve(root, 'public/_locales/en/messages.json')
const outPath = resolve(root, 'src/lib/i18n-keys.d.ts')

const messages = JSON.parse(readFileSync(sourcePath, 'utf8'))
const keys = Object.keys(messages).sort()

const lines = [
  '// AUTO-GENERATED by scripts/gen-i18n-types.js — do not edit by hand.',
  'export type I18nKey =',
  ...keys.map((k) => `  | '${k}'`),
]

writeFileSync(outPath, lines.join('\n') + '\n', 'utf8')
console.log(`Generated ${keys.length} i18n keys -> ${outPath}`)
